-- Return author-written application guidance only after the caller's own submission.
create function public.quiz_learning_recap(target_chapter text, target_activity text, submitted_attempt uuid)
returns jsonb language sql stable security definer set search_path = ''
as $$
  select a.content->'recap'
  from private.chapter_activity_access(target_chapter, auth.uid()) permitted
  join public.activities a on a.id = permitted.id
  join public.quiz_attempts q on q.activity_id = a.id and q.id = submitted_attempt and q.user_id = auth.uid()
  where a.id = target_activity and permitted.unlocked and permitted.type in ('shortQuiz', 'finalQuiz');
$$;
revoke all on function public.quiz_learning_recap(text,text,uuid) from public, anon, authenticated;
grant execute on function public.quiz_learning_recap(text,text,uuid) to authenticated;

update public.activities set content = content || '{"recap":{"summary":["A useful finding links an asset, a weakness, a plausible event and a business consequence.","A recommendation should identify an owner and describe how to verify that the risk was reduced."],"roles":[{"title":"Developer","actions":["Require sign-in before showing customer data. Check on the server that the user''s role permits the action, even if the page already hides that action.","Write a test showing an ordinary user cannot see or change an administrator-only record."]},{"title":"Infrastructure team","actions":["Keep an inventory of the services holding customer data. Assign an owner to patching, backups and monitoring for each service.","Check that backup and recovery jobs are monitored and that a recent restore test exists."]},{"title":"Business owner","actions":["Name the staff who actually need access to customer records and designate someone to approve access changes.","When a staff member leaves, remove access to shared files and applications and record when it was done."]}],"assurance":["Turn a vague finding like “sharing is insecure” into an evidence-backed finding. Record the observed setting, who could be affected, the likely consequence, the agreed owner and how you will retest it."]}}'::jsonb
where id = 'fundamentals' and chapter_id = 'cia-triad' and not (content ? 'recap');

update public.activities set content = content || '{"recap":{"summary":["Confidentiality keeps information from people who should not see it. Integrity keeps it accurate. Availability keeps it usable when needed.","Classify a finding by its observed or plausible effect. A service outage alone does not prove a data breach."],"roles":[{"title":"Developer","actions":["Protect confidentiality with sign-in and server-side role checks. Test that staff can view only the bookings permitted for their role.","Protect integrity by validating changes and recording who edited sensitive booking fields and when."]},{"title":"Infrastructure team","actions":["Agree how much data the business can afford to lose and how long it can be offline. Use those limits to set backup frequency and recovery targets.","Restore a backup to an isolated destination. Check that the restored records are usable and record the time it took."]},{"title":"Business owner","actions":["Review who has access to the booking system. Remove former staff promptly and have someone verify the removal.","Agree on a fallback booking process and assign an owner to practise it with staff."]}],"assurance":["For each CIA objective, ask for a different piece of evidence. For example, check a role test for confidentiality, review an edit record for integrity, and inspect a timed restore for availability."]}}'::jsonb
where id = 'cia-check' and chapter_id = 'cia-triad' and not (content ? 'recap');

update public.activities set content = content || '{"recap":{"summary":["A sound assessment moves from observed evidence to a plausible consequence, then to a control that addresses it.","In the lab, excess editing permissions threatened accuracy, while an untested restore threatened availability. Former staff access was a confidentiality concern."],"roles":[{"title":"Developer","actions":["Require sign-in for private records and enforce role and record-level access on the server. Test an ordinary user, an administrator and a revoked account.","Validate edits and keep an audit trail for sensitive changes such as due dates. Check that a reviewer can identify who acted and what changed."]},{"title":"Infrastructure team","actions":["Agree recovery time and acceptable data loss with the business owner. Keep backups isolated from the main service and secure backup access.","Run a timed restore with representative data, verify record accuracy, and track any failures to an owner and due date."]},{"title":"Business owner","actions":["Approve the recovery targets and fallback process. Assign an owner and a due date to each agreed improvement."]},{"title":"HR","actions":["Notify IT and application owners when a worker leaves or changes roles. Confirm the effective date and record that access removal was acknowledged."]}],"assurance":["Ask each team for evidence, then document what you verified, what remains uncertain, the business impact and a prioritised recommendation. Follow up with a specific retest. This is the distinction between listing controls and providing assurance."]}}'::jsonb
where id = 'chapter-check' and chapter_id = 'cia-triad' and not (content ? 'recap');
